           pre = character(0),
           scripts = "73_cumulative_risk.R"),
  S = list(desc = "Table S3.2 health-reference / hazard-quotient table",
           pre = character(0),
           scripts = "54_health_reference_table.R"),
  R = list(desc = "MDL / smoke / stability / seasonal / CAT-EMU (S1.2, S3.11-S3.14)",
           pre = character(0),
           scripts = c("45_mdl_sensitivity.R", "50_below_mdl_maps.R",
                       "51_cat_emu_comparison.R", "56_hms_smoke_days.R",
                       "57_monthly_stability.R", "62_seasonal_patterns.R"))
)

sel <- Sys.getenv("GROUPS")
run_names <- if (nzchar(sel)) trimws(strsplit(sel, ",")[[1]]) else names(GROUPS)

# ---- DEPENDENCY ORDER (added 2026-08-19) --------------------------------
# Script 31 (group M) REGENERATES hotspot_group_reports/MASTER_hotspot_group_index.csv
# from group_summary_persistent. Script 32 (G) joins TRI onto that index, and
# scripts 33-35 (H) read it to build Figure 4 / fingerprints / directional
# metrics. Alphabetical order runs G and H BEFORE M, so on any run where the
# group set changes (e.g. the native-cadence reprocessing), G and H silently
# use the PREVIOUS run's groups. Worse, scripts 33-35 read the ROOT-level
# MASTER_hotspot_group_index.csv, which is a DIFFERENT file from the one script
# 31 writes under hotspot_group_reports/ — group N (script 71) rebuilds the root
# copy from the current run so the two agree. Force M -> G -> N -> H.
DEP_ORDER <- c("M", "G", "N", "H", "P", "U", "Q", "W", "V")   # U (CH4) before Q (methane@hotspots) and W (attribution)   # P,Q read the rebuilt MASTER
run_names <- c(intersect(DEP_ORDER, run_names), setdiff(run_names, DEP_ORDER))
diag_msg("Run order (dependency-corrected): ", paste(run_names, collapse = ", "))
# -------------------------------------------------------------------------

results <- data.frame(group = character(0), desc = character(0),
                      status = character(0), minutes = numeric(0))

for (g in run_names) {
  if (!g %in% names(GROUPS)) { diag_msg("[SKIP] unknown group: ", g); next }
  gr <- GROUPS[[g]]
  diag_section(paste0("GROUP ", g, ": ", gr$desc))
  # build a temp runner script: libraries -> preloads -> figure scripts
  tmp <- file.path(PIPE, "logs", paste0("figgroup_", g, ".R"))
  lines <- c(
    sprintf('BASE <- "%s"', BASE),
    sprintf('source("%s")', file.path(RS, "01_libraries.R")),
    # 01_libraries loads plyr/raster AFTER dplyr, so select/mutate resolve to
    # the wrong packages in a fresh session (the interactive Rmd sessions had
    # dplyr re-attached on top). Re-attach dplyr LAST so its verbs win.
    'try(detach("package:dplyr"), silent = TRUE)',
    'suppressMessages(library(dplyr, warn.conflicts = FALSE))',
    gr$pre,
    # print.eval=TRUE is ESSENTIAL: knitr auto-prints bare plot objects (p1 etc.)
    # into open jpeg() devices; plain source() does not, silently writing EMPTY
    # figures. print.eval restores knitr-like behavior.
    sprintf('source("%s", echo = FALSE, print.eval = TRUE)', file.path(RS, gr$scripts))
  )
  writeLines(lines, tmp)
  t0 <- Sys.time()
  logf <- file.path(PIPE, "logs", paste0("FIG_", g, "_console.txt"))
  status <- system2("Rscript", tmp, stdout = logf, stderr = logf)
  mins <- round(as.numeric(difftime(Sys.time(), t0, units = "mins")), 1)
  ok <- identical(status, 0L)
  diag_msg(sprintf("  [%s] group %s in %.1f min  (log: %s)",
                   ifelse(ok, "PASS", "FAIL"), g, mins, basename(logf)))
  if (!ok) diag_msg("        last lines of log:\n        ",
                    paste(tail(readLines(logf, warn = FALSE), 5), collapse = "\n        "))
  results <- rbind(results, data.frame(group = g, desc = gr$desc,
                                       status = ifelse(ok, "PASS", "FAIL"), minutes = mins))
}

diag_section("MAKE_FIGURES summary")
for (i in seq_len(nrow(results)))
  diag_msg(sprintf("  [%s] %-2s %-55s %5.1f min",
                   results$status[i], results$group[i], results$desc[i], results$minutes[i]))
n_fail <- sum(results$status == "FAIL")
diag_msg("\n", nrow(results) - n_fail, " groups passed, ", n_fail, " failed.")
if (n_fail > 0) diag_msg("Send the FAIL logs (logs/FIG_<group>_console.txt) back for fixes;",
                         " rerun just those with GROUPS=\"X,Y\" Rscript MAKE_FIGURES.R")
write.csv(results, file.path(PIPE, "figure_generation_summary.csv"), row.names = FALSE)
